    public Claim voidClaim(String sheetId, String user, long id, String voidReason) {
        return changeStatus(sheetId, user, id, ClaimStatus.VOID, null, false, voidReason, false);
    }

    /**
     * Approve a PENDING claim: it becomes SETTLED, its due fixed at its figure (the one a statement bound, else its live one) with its late
     * charge on the sheet's today. Refused (409) when not PENDING, and (403) for a clerk or the
     * user who opened it.
     */
    @Transactional
    public Claim approve(String sheetId, String user, long id) {
        return changeStatus(sheetId, user, id, ClaimStatus.SETTLED, null, true, null, false);
    }

    /**
     * Reject a PENDING claim with a reason: it is OPEN again, still bound by the last statement if
     * that statement included it. Refused (409) when not PENDING, and (403) for a clerk.
     */
    @Transactional
    public Claim reject(String sheetId, String user, long id, String reason) {
        return changeStatus(sheetId, user, id, ClaimStatus.OPEN, reason, true, null, false);
    }

    /**
     * Settle a claim as of a date on or before the sheet's today, as
     * {@link #changeStatus(String, String, long, ClaimStatus)} does, its due fixed at {@code due}: the
     * claim's due as it stood at the end of that date (see {@link ClaimAsOf}). CLAIM_SETTLED gains the
     * date as {@code on=}.
     */
    @Transactional
    public Claim settleAsOf(String sheetId, String user, long id, LocalDate on, BigDecimal due) {
        return changeStatus(sheetId, user, id, ClaimStatus.SETTLED, null, false, null, false, on, due);
    }

    private Claim changeStatus(String sheetId, String user, long id, ClaimStatus next, String reason,
            boolean review, String voidReason, boolean judged) {
        return changeStatus(sheetId, user, id, next, reason, review, voidReason, judged, null, null);
    }

    /**
     * Move a claim to a new status; {@code review} for a steward's approval or rejection of a PENDING
     * claim, {@code judged} when the four-eyes and proof rules were already judged on the claim it was
     * split off (see {@link #partSettle}); {@code on} when settling as of that date, at the due
     * {@code asOfDue} it had then.
     */
    private Claim changeStatus(String sheetId, String user, long id, ClaimStatus next, String reason,
            boolean review, String voidReason, boolean judged, LocalDate on, BigDecimal asOfDue) {
        roles.refuseViewer(sheetId, user);
        if (!review) {
            roles.refuseUnlessPermitted(sheetId, user, switch (next) {
                case OPEN -> "open";
                case SETTLED -> "settle";
                case VOID -> "void";
                default -> throw new IllegalStateException();
            });
        }
        // lock the sheet's numbering before reading the claim, so a claim is opened (and numbered) once
        if (next == ClaimStatus.OPEN) {
            sheets.lock(sheetId);
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Claim claim = claims.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
        ClaimStatus was = claim.getStatus();
        // only a steward's review moves a PENDING claim on, other than voiding it
        // only a steward's review (see #review) moves a REVIEW claim on, other than voiding it
        if (!was.canBecome(next) || (next != ClaimStatus.VOID && review != (was == ClaimStatus.PENDING))
                || (next != ClaimStatus.VOID && was == ClaimStatus.REVIEW)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
        }
        periods.refuseIfClosed(sheetId, claim.getDueBy());
        boolean reversing = was == ClaimStatus.SETTLED;
        if (reversing) {
            refuseVoidSettled(sheetId, user, claim);
        }
        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then.");
        }
        if (next == ClaimStatus.SETTLED && !judged && user.equals(claim.getOpenedBy())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "The user who opened a claim cannot " + (review ? "approve" : "settle") + " it.");
        }
        if (next == ClaimStatus.SETTLED && !judged && user.equals(claim.getEditedBy())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "The user who last edited a claim cannot " + (review ? "approve" : "settle") + " it.");
        }
        if (review && !isSteward(sheetId, user)) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "Only a steward can approve or reject a PENDING claim.");
        }
        String voidedWith = next == ClaimStatus.VOID ? voidReasons.refuseUnlessListed(sheetId, voidReason) : null;
        Person person = person(sheetId, claim.getPersonId());
        if (next == ClaimStatus.OPEN && !review && flaggedAgainst(sheetId, user, person)) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "This person is flagged: only a steward can open their claims.");
        }
        if (next == ClaimStatus.OPEN && !review && atPeriodCap(sheetId, claim)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "This person already has as many open claims in that period as it allows.");
        }
        if (next == ClaimStatus.OPEN && !review && needsNote(sheetId, person, claim)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
                    "A claim due above the note threshold cannot be opened with an empty note.");
        }
        if (next == ClaimStatus.OPEN && !review && needsReview(sheetId, person, claim)) {
            next = ClaimStatus.REVIEW;
        }
        // settling fixes the figure with its late charge as it stands on the sheet's today (a
        // PENDING claim keeps any figure a statement bound)
        BigDecimal settling = next != ClaimStatus.SETTLED ? null
                : on != null ? asOfDue : charged(sheetId, person, claim);
        if (next == ClaimStatus.SETTLED && !judged && needsProof(sheetId, person, claim, settling)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
                    "A claim due above the proof threshold cannot be " + (review ? "approved" : "settled")
                            + " without a proof of each kind the sheet needs.");
        }
        if (next == ClaimStatus.SETTLED && !review && aboveClerkLimit(sheetId, user, person, settling)) {
            next = ClaimStatus.PENDING;
            settling = null;
        }
        claim.setStatus(next);
        if (next == ClaimStatus.OPEN && !review) {
            claim.setNumber(sheets.nextClaimNumber(sheetId, claim.getDueBy()));
            claim.setOpenedBy(user);
        } else if (next == ClaimStatus.REVIEW) {
            claim.setOpenedBy(user);
            claim.setReviewOn(sheets.today(sheetId));
        } else if (next == ClaimStatus.SETTLED) {
            claim.setSettledDue(settling);
        } else if (next == ClaimStatus.VOID) {
            claim.setVoidReason(voidedWith);
        }
        logStatus(sheetId, user, person, claim);
        Claim saved = claims.saveAndFlush(claim);
        String event = switch (next) {
            case OPEN -> review ? "CLAIM_REJECTED" : "CLAIM_OPENED";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> review ? "CLAIM_APPROVED" : "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case REVIEW -> "CLAIM_REVIEW";
            case DRAFT, DELETED -> throw new IllegalStateException();
        };
        audit.recordOnCommit(record(event, sheetId, user, person, saved)
                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
                + (next == ClaimStatus.SETTLED ? " due=" + dueText(saved.getSettledDue()) : "")
                + (reason != null ? " reason=" + reason : "")
                + (reversing ? " reversed=" + dueText(saved.getSettledDue()) : "")
                + (voidedWith != null ? " reason=" + voidedWith : "")
